<script setup lang="ts">
import { ref } from 'vue'
import type { WeekData } from '../../types/study'
import { apiClient } from '../../services/apiClient'
import { useGoogleServices } from '../../composables/useGoogleServices'
const props = defineProps<{ week: WeekData }>(); const emit = defineEmits<{ close: []; processed: [week: WeekData] }>(); const files = ref<File[]>([]); const busy = ref(false); const isDownloadingFromDrive = ref(false); const error = ref(''); const google = useGoogleServices()
async function importFromDrive() { isDownloadingFromDrive.value = true; error.value = ''; try { const selected = await google.pickFiles(); if (selected.length) files.value = [...files.value, ...selected] } catch (e) { error.value = e instanceof Error ? e.message : 'No se pudieron importar los archivos desde Google Drive.' } finally { isDownloadingFromDrive.value = false } }
async function process() { if (!files.value.length) return; busy.value = true; error.value = ''; try { const processed = await apiClient.processWeek(files.value, props.week.modulo, props.week.semana); emit('processed', processed); emit('close'); void Promise.all(files.value.map(file => google.uploadBackup(file))).catch(() => undefined) } catch (e) { error.value = e instanceof Error ? e.message : 'No se pudo procesar el material.' } finally { busy.value = false } }
</script>
<template><div v-if="!isDownloadingFromDrive" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/60 p-4"><div class="card w-full max-w-lg"><div class="flex justify-between"><h2 class="text-xl font-bold">Cargar semana {{ week.modulo }}.{{ week.semana }}</h2><button @click="$emit('close')">✕</button></div><p class="my-4 text-slate-500">Combina archivos PDF y PPTX del material de esta semana.</p><p class="mb-3 text-sm font-medium" :class="google.connected ? 'text-emerald-600' : 'text-slate-500'">{{ google.connected ? `Drive conectado: ${google.userEmail || 'cuenta Google'}` : 'Drive desconectado' }}</p><input type="file" accept=".pdf,.pptx" multiple class="w-full rounded-xl border p-3" @change="files = Array.from(($event.target as HTMLInputElement).files || [])" /><button class="btn-muted mt-3 w-full" :disabled="isDownloadingFromDrive || !google.connected" @click="importFromDrive">{{ isDownloadingFromDrive ? 'Descargando desde Drive…' : 'Importar desde Google Drive' }}</button><p v-if="!google.connected" class="mt-2 text-xs text-slate-500">Conecta Google desde el encabezado para importar archivos.</p><p v-if="files.length" class="mt-3 text-sm text-slate-500">{{ files.length }} archivo(s) seleccionado(s)</p><p v-if="google.error" class="mt-2 text-sm text-amber-600">{{ google.error }}</p><p v-if="error" class="mt-3 rounded-xl bg-red-50 p-3 text-red-700">{{ error }} <button class="font-bold underline" @click="process">Reintentar procesamiento</button></p><button class="btn-primary mt-5 w-full" :disabled="busy || !files.length" @click="process">{{ busy ? 'Procesando…' : 'Procesar material' }}</button></div></div><div v-else class="fixed inset-0 z-40 grid place-items-center bg-slate-950/20 p-4"><div class="rounded-xl bg-white px-5 py-3 shadow-lg dark:bg-slate-900">Descargando archivos desde Google Drive…</div></div></template>
